import { AppShell, Button, ConsentCheckbox, Field } from "@wizard/ui-kit";
import { useEntityMutation, useState } from "@wizard/sdk";

export default function Main() {
  const [form, setForm] = useState({ name: "", phone: "", consent: false });
  const requests = useEntityMutation("request");
  return (
    <AppShell title={"Керамическая мастерская: интернет-магазин с оплатой ЮKassa, доставкой СДЭК и самовывозом"}>
      <p>{"Мы небольшая керамическая мастерская из Твери: кружки, тарелки, вазы ручной работы, многие вещи в одном-двух экземплярах. Нужен интернет-магазин: каталог с фото, ценами и разделами, у каждого товара видно, сколько осталось. Покупатель кладёт товары в корзину, оформляет заказ и сразу платит картой на сайте через ЮKassa, с чеком по 54-ФЗ на почту. Получить заказ можно самовывозом из мастерской или доставкой СДЭК до пункта выдачи — покупатель пишет город и выбирает пункт, цену доставки считаем сразу. Если заказ не оплачен в течение часа, он отменяется и товар возвращается в продажу. Важно, чтобы последнюю кружку не купили двое. Владелица в кабинете видит заказы, оплаты и остатки, меняет статусы и вписывает трек-номер СДЭК. Товары и остатки ведёт сама. Хотим спокойный сайт, как каталог небольшой галереи. Для зарубежных покупателей у нас пишет клиент, её почта клиент."}</p>
      <ul>
        <li>{"Корзина"}</li>
        <li>{"Оплата ЮKassa"}</li>
        <li>{"Доставка СДЭК"}</li>
        <li>{"Самовывоз"}</li>
      </ul>
      <p>{"Последний товар не продаётся дважды"}</p>
      <p>{"Неоплаченный заказ отменяется"}</p>
      <form onSubmit={(e) => { e.preventDefault(); void requests.create({ contact_name: form.name, contact_phone: form.phone }, { consent: true }); }}>
        <Field name="contact_name" label="Имя" type="string" value={form.name} onChange={(v) => setForm({ ...form, name: String(v) })} />
        <Field name="contact_phone" label="Телефон" type="phone" value={form.phone} onChange={(v) => setForm({ ...form, phone: String(v) })} />
        <ConsentCheckbox checked={form.consent} onChange={(v) => setForm({ ...form, consent: v })} />
        <Button type="submit">{"Отправить заявку"}</Button>
      </form>
    </AppShell>
  );
}
